spec.setup_code:
function mk(s){return function(){s|=0;s=s+0x6D2B79F5|0;var t=Math.imul(s^s>>>15,1|s);t=t+Math.imul(t^t>>>7,61|t)^t;return((t^t>>>14)>>>0)/4294967296;};}
var rnd=mk(7);
var Z=[];
for(var i=0;i<36;i++){var a=Math.max(rnd(),1e-6),b=rnd();var r=Math.sqrt(-2*Math.log(a));Z.push([r*Math.cos(6.2832*b),r*Math.sin(6.2832*b)]);}
var BLUE='#0B4FC0',WARM='#B4552F',INK='#04204B',SEC='#3D5F91',FAINT='#8098BC',GREY='#8098BC';
var PERIOD=14;
var X=[0.1,0.2],D0=[0.34,0.42],DC=[0.43,0.49],FOX=[0.62,0.6],CLUMP=[0.74,0.7];
var CL=[[0.2,0.66,'cat'],[0.4,0.14,'bird']];
var WS=[[0,2.5,1,1],[2.5,6.5,1,7],[6.5,7.5,7,7],[7.5,8.5,7,1],[8.5,10,1,1],[10,12.5,1,7],[12.5,13.2,7,7],[13.2,14,7,1]];
function sm(x){x=Math.max(0,Math.min(1,x));return x*x*(3-2*x);}
function wAt(t){for(var i=0;i<WS.length;i++){var s=WS[i];if(t<s[1]||i==WS.length-1){return s[2]+(s[3]-s[2])*sm((t-s[0])/(s[1]-s[0]));}}return 1;}
function draw(ctx,width,height,time,dt){
 ctx.fillStyle='#ffffff';ctx.fillRect(0,0,width,height);
 var t=time%PERIOD;
 var w=wAt(t);
 var u=(w-1)/6;
 var sa=sm((t-7.5)/1)*(1-sm((t-13.2)/0.8));
 var aa=1-0.75*sa;
 var m=14,px=m,py=34,pw=width-2*m,ph=height-34-82;
 function X_(v){return px+v*pw;}
 function Y_(v){return py+ph-v*ph;}
 ctx.font='12px sans-serif';ctx.textBaseline='alphabetic';
 function label(s,x,y,col,center){var tw=ctx.measureText(s).width;var l=center?x-tw/2:x;l=Math.max(4,Math.min(width-4-tw,l));ctx.fillStyle=col;ctx.textAlign='left';ctx.fillText(s,l,y);}
 var cap;
 if(t<2.5)cap='Same noisy x, two predictions';
 else if(t<7.5)cap='Extrapolate: D_w = D(∅) + w·(D(c) − D(∅))';
 else if(t<10)cap='w = 1: samples spread over the fox cluster';
 else if(t<13.2)cap='w = 7: crowded at the far edge of the cluster';
 else cap='Back to w = 1';
 ctx.font='13px sans-serif';label(cap,width/2,20,INK,true);ctx.font='12px sans-serif';
 ctx.strokeStyle='#d5deec';ctx.lineWidth=1;ctx.strokeRect(px,py,pw,ph);
 function cont(c,col,al){ctx.strokeStyle=col;ctx.globalAlpha=al;ctx.lineWidth=1;for(var k=1;k<=3;k++){ctx.beginPath();ctx.ellipse(X_(c[0]),Y_(c[1]),pw*0.055*k,ph*0.075*k,0,0,6.2832);ctx.stroke();}ctx.globalAlpha=1;}
 for(var j=0;j<CL.length;j++){cont(CL[j],GREY,0.8);label(CL[j][2],X_(CL[j][0]),Y_(CL[j][1])-ph*0.075*3-4,SEC,true);}
 cont(FOX,BLUE,0.9);
 label('fox (c)',X_(FOX[0]),Y_(FOX[1])-ph*0.075*3-4,BLUE,true);
 function arrow(x0,y0,x1,y1,col,lw,al){var dx=x1-x0,dy=y1-y0,L=Math.sqrt(dx*dx+dy*dy)||1;dx/=L;dy/=L;ctx.globalAlpha=al;ctx.strokeStyle=col;ctx.fillStyle=col;ctx.lineWidth=lw;ctx.beginPath();ctx.moveTo(x0,y0);ctx.lineTo(x1-dx*6,y1-dy*6);ctx.stroke();ctx.beginPath();ctx.moveTo(x1,y1);ctx.lineTo(x1-dx*9-dy*4.5,y1-dy*9+dx*4.5);ctx.lineTo(x1-dx*9+dy*4.5,y1-dy*9-dx*4.5);ctx.closePath();ctx.fill();ctx.globalAlpha=1;}
 var xs=X_(X[0]),ys=Y_(X[1]);
 var d0x=X_(D0[0]),d0y=Y_(D0[1]),dcx=X_(DC[0]),dcy=Y_(DC[1]);
 var gx=D0[0]+w*(DC[0]-D0[0]),gy=D0[1]+w*(DC[1]-D0[1]);
 var gpx=X_(gx),gpy=Y_(gy);
 if(w>1.02){ctx.setLineDash([4,4]);ctx.strokeStyle=WARM;ctx.globalAlpha=0.5*aa;ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(d0x,d0y);ctx.lineTo(gpx,gpy);ctx.stroke();ctx.setLineDash([]);ctx.globalAlpha=1;}
 var warmA=sm((t-2.5)/0.8)*aa;
 if(t>=7.5)warmA=aa;
 arrow(xs,ys,gpx,gpy,WARM,4,warmA);
 arrow(xs,ys,dcx,dcy,BLUE,2.2,aa);
 arrow(xs,ys,d0x,d0y,GREY,2.2,aa);
 ctx.globalAlpha=aa;
 ctx.fillStyle=INK;ctx.beginPath();ctx.arc(xs,ys,4.5,0,6.2832);ctx.fill();
 label('x (noisy, σ)',xs+8,ys+16,INK,false);
 label('D(x,σ|∅)',d0x+2,d0y+17,SEC,true);
 label('D(x,σ|c)',dcx-4,dcy-9,BLUE,true);
 if(w>1.6){ctx.globalAlpha=Math.min(1,(w-1.6)/1)*aa;label('D_w, w = '+w.toFixed(1),gpx-4,gpy-10,WARM,true);}
 ctx.globalAlpha=1;
 if(sa>0.01){
  ctx.globalAlpha=sa*0.85;
  for(var q=0;q<Z.length;q++){
   var sd=0.065+(0.014-0.065)*sm(u);
   var cx=FOX[0]+(CLUMP[0]-FOX[0])*sm(u),cy=FOX[1]+(CLUMP[1]-FOX[1])*sm(u);
   var sx=cx+sd*Z[q][0]*0.9,sy=cy+sd*Z[q][1]*1.0;
   ctx.fillStyle=u<0.5?BLUE:WARM;
   ctx.beginPath();ctx.arc(X_(sx),Y_(sy),3,0,6.2832);ctx.fill();
  }
  ctx.globalAlpha=1;
  label('samples x₀ | c, w = '+w.toFixed(1),X_(FOX[0]),Y_(FOX[1])+ph*0.075*3+14,u<0.5?BLUE:WARM,true);
 }
 var sy2=height-50,sx0=px+64,sx1=width-m-16;
 ctx.font='12px sans-serif';
 label('w = '+w.toFixed(1),px,sy2+4,WARM,false);
 ctx.strokeStyle=FAINT;ctx.lineWidth=3;ctx.beginPath();ctx.moveTo(sx0,sy2);ctx.lineTo(sx1,sy2);ctx.stroke();
 var kx=sx0+(sx1-sx0)*u;
 ctx.strokeStyle=WARM;ctx.beginPath();ctx.moveTo(sx0,sy2);ctx.lineTo(kx,sy2);ctx.stroke();
 ctx.fillStyle='#ffffff';ctx.strokeStyle=WARM;ctx.lineWidth=2.5;ctx.beginPath();ctx.arc(kx,sy2,7,0,6.2832);ctx.fill();ctx.stroke();
 label('1',sx0,sy2+22,SEC,true);label('7',sx1,sy2+22,SEC,true);
 var na=sm((t-10.3)/0.8)*(1-sm((t-13.2)/0.6));
 ctx.globalAlpha=na;
 ctx.font='13px sans-serif';
 label('higher w: more on-prompt, less diverse',width/2,height-8,WARM,true);
 ctx.globalAlpha=1;
}
return {draw:draw};
